/*
 * Classifies ARP_EXAMPLE after its parent ethernet (plugin.yaml): when
 * every match holds on the parent's bytes, ARP_EXAMPLE starts 14 bytes
 * after the start of the parent, at previous_index + 1.
 */
static mmt_classify_verdict_t arp_example_classify_after_ethernet(ipacket_t *ipacket, unsigned previous_index)
{
    classified_proto_t next;
    int64_t caplen = (int64_t) ipacket->p_hdr->caplen;
    int64_t start = (int64_t) get_packet_offset_at_index(ipacket, previous_index);
    const uint8_t *p;

    if (start < 0 || start > caplen - 14) {
        return MMT_CLASSIFY_SKIP;
    }
    p = &ipacket->data[start];
    if ((((uint64_t) p[12] << 8) | (uint64_t) p[13]) != 0x806u) {
        return MMT_CLASSIFY_SKIP;
    }
    memset(&next, 0, sizeof(next));
    next.proto_id = PROTO_ARP_EXAMPLE;
    next.offset = 14;
    next.status = Classified;
    if (!set_classified_proto(ipacket, previous_index + 1, next)) {
        return MMT_CLASSIFY_SKIP;
    }
    return MMT_CLASSIFY_MATCHED;
}

